<script setup lang="ts">
import { useCardMotion } from '../composables/useCardMotion'
import InputNumber from 'primevue/inputnumber'

import { ref,watch,computed } from 'vue'
import { useGarage } from '../stores/garage'
import { api } from '../services/api'
import type { Indicators } from '../services/types'
import { money,categories } from '../services/types'
import ExpenseChart from '../components/ExpenseChart.vue'
import EmptyState from '../components/EmptyState.vue'
const g=useGarage(),year=ref(new Date().getFullYear()),data=ref<Indicators|null>(null),error=ref(''),busy=ref(false)
let request=0
watch([year,()=>g.selectedId,()=>g.dataRevision],async()=>{if(!g.selectedId)return;const v=++request;busy.value=true;error.value='';try{const result=await api<Indicators>(`/vehicles/${g.selectedId}/indicators?year=${year.value}`);if(v===request)data.value=result}catch(e){if(v===request)error.value=(e as Error).message}finally{if(v===request)busy.value=false}},{immediate:true})
const yearTotal=computed(()=>data.value?.monthly.reduce((s,m)=>s+m.total,0)??0)
const { cardInitial, cardEnter } = useCardMotion()
</script>
<template><template v-if="g.selected"><p class="view-description">Entenda os gastos e planeje os próximos quilômetros.</p><p v-if="error" class="error-banner" role="alert">{{error}}</p><p v-if="busy" role="status" class="muted">Calculando despesas…</p><template v-if="data"><div class="finance-totals metrics-strip" :class="{'finance-totals--mixed':data.unallocated>0||data.interest>0}"><div><span class="stat-label">{{data.pendingPaymentCount?'Total conhecido':'Total acumulado'}}</span><strong>{{money(data.total)}}</strong><small>Todos os serviços do veículo</small></div><div><span class="stat-label">Peças</span><strong>{{money(data.parts)}}</strong><small>Valores detalhados</small></div><div><span class="stat-label">Mão de obra</span><strong>{{money(data.labor)}}</strong><small>Valores detalhados</small></div><div v-if="data.interest>0"><span class="stat-label">Juros e acréscimos</span><strong>{{money(data.interest)}}</strong><small>Separados de peças e mão de obra</small></div><div v-if="data.unallocated>0"><span class="stat-label">Sem detalhamento</span><strong>{{money(data.unallocated)}}</strong><small>Valores totais fechados</small></div></div><p v-if="data.pendingPaymentCount" class="form-hint finance-cost-hint payment-pending" role="status">Há {{data.pendingPaymentCount}} {{data.pendingPaymentCount===1?'cobrança com juros ainda não informados':'cobranças com juros ainda não informados'}}. O total conhecido não inclui esses juros pendentes.</p><p v-if="data.unallocated>0" class="form-hint finance-cost-hint">Valores totais fechados entram no total acumulado sem divisão entre peças e mão de obra.</p><div class="finance-grid"><article v-motion :initial="cardInitial" :enter="cardEnter()" class="panel expense-panel"><div class="section-header"><div><h2>Despesas mensais</h2><p class="muted">{{money(yearTotal)}} em {{year}}</p></div><label class="year-select" for="finance-year">Ano<InputNumber input-id="finance-year" v-model="year" :min="1900" :max="9999" :use-grouping="false" /></label></div><ExpenseChart :data="data.monthly"/></article><article v-motion :initial="cardInitial" :enter="cardEnter(60)" class="panel category-panel"><h2>Por categoria</h2><p class="muted">Distribuição de todo o histórico</p><div v-for="c in data.categories" :key="c.category" class="category-item"><div class="data-row"><span>{{categories[c.category]}}</span><strong>{{money(c.total)}}</strong></div><div class="category-track"><span :style="{width:(data.total?c.total/data.total*100:0)+'%'}"></span></div></div><EmptyState v-if="!data.categories.length" title="Cada gasto no seu lugar" description="As categorias aparecerão com seus primeiros registros."/></article></div><div class="finance-grid"><article v-motion :initial="cardInitial" :enter="cardEnter(90)" class="panel list-panel"><h2>Gastos por ano</h2><div v-for="a in data.annual" :key="a.year" class="data-row"><span>{{a.year}}</span><strong>{{money(a.total)}}</strong></div><p v-if="!data.annual.length" class="muted">Ainda não há despesas registradas.</p></article><article v-motion :initial="cardInitial" :enter="cardEnter(90)" class="panel list-panel"><h2>Serviços de maior valor</h2><RouterLink v-for="r in data.mostExpensive" :key="r.id" to="/historico" class="data-row"><span>{{r.description}}</span><strong>{{money(r.totalCost)}}</strong></RouterLink><p v-if="!data.mostExpensive.length" class="muted">Registre um serviço para começar.</p></article></div></template></template><EmptyState v-else title="Selecione um veículo" description="Os gastos são organizados por veículo."/></template>
